import{_ as n}from"./chunks/image12.BRgDBKom.js";import{_ as i,o,c as r,am as a}from"./chunks/framework.CenUaW7a.js";const s="/projects/AiMechaM1/en/advanced-kit/assets/image1.D79fqnIg.webp",t="/projects/AiMechaM1/en/advanced-kit/assets/image2.CETa_1F7.png",l="/projects/AiMechaM1/en/advanced-kit/assets/image3.KxQ18IXu.png",c="/projects/AiMechaM1/en/advanced-kit/assets/image4.g9SpFFuU.png",g="/projects/AiMechaM1/en/advanced-kit/assets/image5.BapPkz3R.png",d="/projects/AiMechaM1/en/advanced-kit/assets/image6.DhTtQTUJ.png",p="/projects/AiMechaM1/en/advanced-kit/assets/image7.b4f-xDsi.png",m="/projects/AiMechaM1/en/advanced-kit/assets/image8.CgHcD94C.png",h="/projects/AiMechaM1/en/advanced-kit/assets/image9.CQWM63pf.png",D=JSON.parse('{"title":"3.20 Lesson 20: Dynamic Gesture Interaction","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.20 Lesson 20 Dynamic Gesture Interaction.md","filePath":"docs/3. Course materials/3.20 Lesson 20 Dynamic Gesture Interaction.md"}'),u={name:"docs/3. Course materials/3.20 Lesson 20 Dynamic Gesture Interaction.md"};function f(y,e,b,w,v,x){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="_3-20-lesson-20-dynamic-gesture-interaction" tabindex="-1">3.20 Lesson 20: Dynamic Gesture Interaction <a class="header-anchor" href="#_3-20-lesson-20-dynamic-gesture-interaction" aria-label="Permalink to &quot;3.20 Lesson 20: Dynamic Gesture Interaction&quot;">​</a></h1><h2 id="_3-20-1-lesson-introduction" tabindex="-1">3.20.1 Lesson Introduction <a class="header-anchor" href="#_3-20-1-lesson-introduction" aria-label="Permalink to &quot;3.20.1 Lesson Introduction&quot;">​</a></h2><p>Taking inspiration from science fiction mid-air gesture control and motion-sensing games, this lesson explores three core technologies: fixed gestures, custom palm keypoints, and dynamic gestures. Three progressive tasks are completed: controlling the robotic arm with standard gestures, triggering lights with custom gestures, and driving the Mecanum-wheel car with dynamic gestures, mastering static classification, custom learning, and temporal recognition. By introducing temporal dynamic recognition for the first time, this lesson highlights the distinction between continuous frame tracking and static classification, completing the comprehensive vision capabilities of the K230 module and establishing a static-to-dynamic gesture interaction system that lays the foundation for large model interaction.</p><h2 id="_3-20-2-learning-objectives" tabindex="-1">3.20.2 Learning Objectives <a class="header-anchor" href="#_3-20-2-learning-objectives" aria-label="Permalink to &quot;3.20.2 Learning Objectives&quot;">​</a></h2><p><strong>1.</strong> Understand the contour matching principle of fixed gesture recognition, the feature distribution concepts of palm keypoints, and the temporal trajectory analysis method of dynamic gesture recognition.</p><p><strong>2.</strong> Utilize built-in standard gestures such as thumbs-up and victory to control robotic arm movements. Complete the learning registration and ID naming of custom palm keypoint gestures to trigger multicolored light feedback.</p><p><strong>3.</strong> Establish a technical layering framework for gesture interaction, understanding the capability progression from static to dynamic and from general to custom. Cultivate design thinking for non-contact human-robot interaction and reflect on experience design principles for natural interaction.</p><p><strong>4.</strong> Connect gesture interaction to real-world application scenarios such as smart TV gesture control, VR motion-sensing interaction, sign language translation, smart home mid-air control, and sterile industrial gesture operations, understanding the application value of gesture interaction across various fields.</p><h2 id="_3-20-3-preparation" tabindex="-1">3.20.3 Preparation <a class="header-anchor" href="#_3-20-3-preparation" aria-label="Permalink to &quot;3.20.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation</strong>:</p><ul><li><p>AiMecha M1 Mecanum-Wheel Car Advanced Kit</p></li><li><p>Type-C data cable</p></li><li><p>Computer × 1</p></li><li><p>Remote controller</p></li></ul><p><strong>Software Preparation</strong>:</p><ul><li>WonderLab graphical programming software</li></ul><p><strong>Comparison of Three Gesture Recognition Functions</strong>:</p><ul><li><p><strong>Fixed Gesture Recognition</strong>: Features a built-in pre-trained model supporting standard gestures such as thumbs-up, victory, OK, and numbers, ready for use without prior learning.</p></li><li><p><strong>Custom Palm Keypoints</strong>: Locates 21 keypoints on the palm to support learning custom static gestures with custom designs and ID names.</p></li><li><p><strong>Dynamic Gesture Recognition</strong>: Tracks the motion trajectory of the palm across continuous frames to recognize dynamic movements such as waving and swiping, which requires prior recording and learning.</p></li></ul><p><strong>Wiring Instructions</strong>:</p><ul><li><p>Connect the K230 screen module to <strong>port A</strong> of the controller.</p></li><li><p>Connect the three bus servos in series to bus port S1 or S2.</p></li><li><p>Mount the camera at a height level with the palm, at a distance of 30 cm to 60 cm for optimal recognition.</p></li></ul><p><strong>Gesture Learning Operating Standards</strong>:</p><ul><li><p>Static gesture learning: Enter the palm keypoints mode → tap Learn → hold the gesture steady for 2 s → save it under an ID name.</p></li><li><p>Dynamic gesture learning: Enter the dynamic gesture mode → tap Learn → perform the complete movement once → allow automatic recording → save it under an ID name.</p></li><li><p>Naming convention: Use English letters or numbers for ID names without Chinese characters, such as ID1, ID2, open, or close.</p></li><li><p>Learning environment: Maintain uniform lighting and a clean background to avoid complex background interference during recognition.</p></li></ul><p><strong>Built-In Standard Gesture List</strong>:</p><ul><li><p>Thumbs Up: Holding up the thumb.</p></li><li><p>Victory: Making a V-shaped scissor sign with fingers.</p></li><li><p>OK Gesture: Forming a circle with the thumb and index finger.</p></li><li><p>Palm: Spreading all five fingers open.</p></li><li><p>Fist: Clenching the hand into a fist.</p></li></ul><h2 id="_3-20-4-hands-on-project" tabindex="-1">3.20.4 Hands-On Project <a class="header-anchor" href="#_3-20-4-hands-on-project" aria-label="Permalink to &quot;3.20.4 Hands-On Project&quot;">​</a></h2><p><strong>1. Program Logic</strong></p><p>This lesson builds a three-tier progressive gesture interaction system. The fixed gesture mode matches pre-trained templates such as thumbs-up and victory to trigger robotic arm lifting and lowering. The palm keypoint mode locates 21 skeletal points to compare self-learned custom gestures and trigger RGB LED feedback. The dynamic mode tracks keypoint temporal trajectories against pre-recorded templates to drive the car forward and illuminate yellow lights. All three modes share a unified framework of initialization, data updating, and conditional judgment, advancing detection from single-frame static analysis to multi-frame dynamic understanding and illustrating the progression from spatial to spatiotemporal vision processing.</p><img loading="lazy" height="442" width="960" src="'+s+'" class="common_img" style="width:600px;aspect-ratio:960 / 442;"><p>💡<strong>Complete Program Preview:</strong></p><img loading="lazy" height="817" width="942" src="'+t+'" class="common_img" style="width:600px;aspect-ratio:942 / 817;"><p><strong>2. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Fixed gesture</td><td style="text-align:center;"><img loading="lazy" height="376" width="667" src="'+l+'" class="common_img" style="width:300px;aspect-ratio:667 / 376;"></td><td style="text-align:left;">Evaluates standard gesture types and returns the classification result.</td></tr><tr><td style="text-align:center;">Palm detection</td><td style="text-align:center;"><img loading="lazy" height="54" width="281" src="'+c+'" class="common_img" style="width:200px;aspect-ratio:281 / 54;"></td><td style="text-align:left;">Determines whether a palm is present in the frame.</td></tr><tr><td style="text-align:center;">Custom gesture</td><td style="text-align:center;"><img loading="lazy" height="78" width="588" src="'+g+'" class="common_img" style="width:300px;aspect-ratio:588 / 78;"></td><td style="text-align:left;">Evaluates whether a self-learned custom static gesture appears in the frame.</td></tr><tr><td style="text-align:center;">Palm parameters</td><td style="text-align:center;"><img loading="lazy" height="443" width="655" src="'+d+'" class="common_img" style="width:300px;aspect-ratio:655 / 443;"></td><td style="text-align:left;">Reads palm keypoint names, confidence scores, and joint coordinates.</td></tr><tr><td style="text-align:center;">Dynamic gesture detection</td><td style="text-align:center;"><img loading="lazy" height="77" width="551" src="'+p+'" class="common_img" style="width:300px;aspect-ratio:551 / 77;"></td><td style="text-align:left;">Evaluates whether a custom dynamic gesture movement is recognized.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task 1: Fixed Gesture Controlling Robotic Arm Lifting and Lowering</strong></p><ul><li><p>Initialization settings: At startup, reset all three bus servos to position 500 with a running time of 500 ms, initialize port A, set the running mode to gesture recognition, start detection, set the onboard RGB LEDs to dazzling mode, and turn off the ultrasonic sensor RGB lights.</p></li><li><p>Main loop structure: Execute <code>Update and save result data</code> as the first step inside the repeat forever loop to synchronize the latest gesture data.</p></li><li><p>Thumbs-up response: If <code>Get the near-center gesture recognition result as Like</code>, execute the action sequence: set servo ID 1 to position 500 to close the gripper, set servo ID 3 to position 500 to raise the robotic arm, and wait 1 s to complete the greeting lift.</p></li><li><p>Victory response: If <code>Get the near-center gesture recognition result as victory</code>, execute the action sequence: set servo ID 1 to position 900 to open the gripper, set servo ID 3 to position 300 to lower the robotic arm, and wait 1 s to complete the lowering and opening maneuver.</p></li><li><p>Parameter explanation: Position 500 on servo ID 3 represents the high position, and 300 represents the low position, while position 500 on servo ID 1 represents closing and 900 represents opening, linking the two gestures to distinct robotic arm postures.</p></li></ul><img loading="lazy" height="833" width="619" src="'+m+'" class="common_img" style="width:460px;aspect-ratio:619 / 833;"><p><strong>Task 2: Custom Palm Gesture Triggering RGB LEDs</strong></p><ul><li><p>Gesture learning preparation: Operate the palm keypoint function on the K230 module to learn two custom gestures named ID2 and ID3, keeping the hand steady during learning without using Chinese characters for names.</p></li><li><p>Mode reuse: The gesture recognition mode simultaneously supports palm keypoint detection, allowing both functions to be mixed within the same program without switching modes.</p></li><li><p>ID2 gesture response: If <code>Whether palm gesture is detected ID2?</code> is true, execute the actions: stop the car, set all ultrasonic sensor RGB lights to blue, and illuminate the onboard RGB LEDs in blue as the second state indicator.</p></li><li><p>ID3 gesture response: If <code>Whether palm gesture is detected ID3?</code> is true, execute the actions: stop the car, set all ultrasonic sensor RGB lights to red, and illuminate the onboard RGB LEDs in red as the third state indicator.</p></li><li><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p></p><p><strong>Expansion suggestion: Learn additional custom gestures corresponding to different colors to build a complete set of gesture-driven lighting commands.</strong></p></div></li></ul><img loading="lazy" height="849" width="1213" src="'+h+'" class="common_img" style="width:600px;aspect-ratio:1213 / 849;"><p><strong>Task 3: Dynamic Gesture Controlling Car Forward Movement</strong></p><ul><li><p>Dynamic gesture learning: Enter the dynamic gesture function on the K230 module and record a forward waving motion as the startup gesture, assigned the ID name ID1. Perform the movement smoothly and fluently from start to finish during recording.</p></li><li><p>Initialization configuration: Similar to the gesture recognition mode, dynamic gestures run under the gesture recognition mode.</p></li><li><p>Action trigger: If <code>Get the dynamic gesture as ID1</code> executes to true, execute the actions: move the Mecanum-wheel car forward at 30% power, illuminate the ultrasonic sensor RGB lights in yellow, wait 2 s, and stop the car to complete a forward movement command.</p></li><li><p>Program outcome: Waving forward toward the camera automatically drives the car forward for 2 s before stopping, achieving wave-to-go contactless control.</p></li><li><p>Debugging tip: Dynamic gesture recognition requires consistent movement speed and amplitude during both learning and usage, as excessive speed causes hand motion blur and reduces recognition accuracy.</p></li></ul><img loading="lazy" height="817" width="942" src="'+t+'" class="common_img" style="width:600px;aspect-ratio:942 / 817;"><p><strong>General Debugging Tips for Gesture Interaction</strong></p><ul><li><p>Distance control: Maintain a distance of 30 cm to 60 cm between the palm and the camera, as being too far makes the hand too small to see, while being too close exceeds the field of view.</p></li><li><p>Angle requirement: Pointing the palm directly toward the camera yields the best results, whereas side or back hand orientations degrade recognition rates.</p></li><li><p>Lighting requirements: Use uniform lighting to avoid backlighting or direct strong light causing hand overexposure.</p></li><li><p>Clean background: A solid, simple background ensures the most accurate recognition, whereas cluttered backgrounds interfere with feature extraction.</p></li><li><p>Distinctive design: Maximize visual differences between custom gestures to prevent similar gestures from causing misrecognition.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1qESIR7n_mxv3oQTrZhNbBTnPKVOk-yT4?usp=sharing" target="_blank" rel="noreferrer">Program Files/Dynamic Gesture Interaction</a>.</strong></p></div></li></ul><p><strong>Program Upload</strong>:</p><ul><li><p>Step 1: Power on the mecha controller and insert the Type-C data cable into the data port located above the power switch on the controller.</p></li><li><p>Step 2: Connect the other end of the data cable to a USB port on the computer.</p></li><li><p>Step 3: Click the <strong>Connect device</strong> button at the top of the software interface and select the COM port corresponding to CH340 from the port list.</p></li><li><p>Step 4: Click the upload button in the upper-right corner to download the compiled program to the mecha controller for execution.</p></li></ul><img loading="lazy" height="508" width="960" src="'+n+'" class="common_img" style="width:800px;aspect-ratio:960 / 508;"><h2 id="_3-20-5-expansion-and-advancement" tabindex="-1">3.20.5 Expansion and Advancement <a class="header-anchor" href="#_3-20-5-expansion-and-advancement" aria-label="Permalink to &quot;3.20.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Expansion Project 1: Complete Gesture Remote Control System</strong></p><p>Design a comprehensive gesture control scheme that maps five gestures to five car actions, moving forward, moving backward, turning left, turning right, and stopping, to enable fully gesture-driven driving. Incorporate robotic arm gesture controls by assigning three additional gestures to control gripper opening/closing and arm lifting/lowering, ultimately achieving full 8-gesture control over the car to completely replace handheld remote controllers and experience true contactless motion sensing.</p><p><strong>Expansion Project 2: Dynamic Gesture Sign Language Translator</strong></p><p>Learn multiple dynamic gesture movements corresponding to different meanings, such as common sign language phrases like &quot;hello&quot;, &quot;thank you&quot;, and &quot;goodbye&quot;. When the system recognizes a corresponding gesture, trigger the buzzer to play different musical pitches or display the textual meaning on the screen. Explore the mapping relationship between gesture language and machine commands to understand the basic principles of sign language translation and how AI assists communication for the hearing-impaired.</p><h2 id="_3-20-6-q-a" tabindex="-1">3.20.6 Q&amp;A <a class="header-anchor" href="#_3-20-6-q-a" aria-label="Permalink to &quot;3.20.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: What are the fundamental technical differences among the three recognition methods: fixed gestures, custom palm gestures, and dynamic gestures?</strong></p><p><strong>Answer</strong>: The fundamental differences lie in their <strong>recognition dimensions and customization levels</strong>, representing three technological tiers of gesture recognition.</p><p>Fixed gesture recognition performs single-frame image classification. Custom palm gestures involve keypoint feature matching. Dynamic gesture recognition relies on temporal trajectory matching.</p><p><strong>Q2: Why do custom palm gestures and dynamic gestures require prior learning, whereas fixed gestures work immediately without learning?</strong></p><p><strong>Answer</strong>: Fixed gestures require no learning because they are <strong>pre-trained on large datasets prior to manufacturing</strong>, meaning the system has already learned them. Custom and dynamic gestures require learning because individual gestures vary, and the machine cannot predict in advance which custom movements are to be defined.</p><h2 id="_3-20-7-technical-support-and-discussion" tabindex="-1">3.20.7 Technical Support and Discussion <a class="header-anchor" href="#_3-20-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.20.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',57)])])}const I=i(u,[["render",f]]);export{D as __pageData,I as default};
